function significantLines(data: Buffer): string[] {
  return data.toString("latin1").split("\n").map((l) => l.trim())
    .filter((l) => l.length >= SIGNIFICANT_LINE_MIN && !l.startsWith("#") && !l.startsWith("//") && /[A-Za-z0-9]/.test(l));
