  const out = diffOf(d);
  assert.match(out.diff, /VISIBLE_EDIT/);
  assert.doesNotMatch(out.diff, /deleted file mode/);
});

test("a debugger snapshot of a sparse worktree keeps out-of-cone files and does not fail on an untracked one there", () => {
